INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT156-S4-Q16$batch02$, 156, 4, 16, $batch02$Flaw$batch02$, $batch02$Manager: I plan to put together a successful marketing team by choosing highly skilled, independent workers who prefer not to work as part of a tightly knit group. This strategy is bound to succeed because recent research shows that when a common purpose is shared, the flexibility of loosely bound groups enables them to function better than tightly knit ones.$batch02$, $batch02$The reasoning in the manager’s argument is most vulnerable to criticism on the grounds that the argument$batch02$, $batch02$D$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=156 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q16$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$presumes that factors that are collectively sufficient for success are also individually necessary for success$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q16$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$relies on research that has no apparent relevance to the manager’s proposed plan$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q16$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$takes for granted that flexible teams always function significantly better than inflexible teams$batch02$, $batch02$Too Strong$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q16$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$overlooks the possibility that people who prefer not to work in tightly knit groups may have difficulty committing to a common purpose$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q16$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$confuses the goals that the manager is seeking to achieve with the goals that must be held in common by the members of the marketing team$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q16$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q16$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$The plan to hire independent workers who avoid tight groups is bound to succeed.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$*When a common purpose is shared*, loose groups function better than tight ones.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$The research has a condition attached: a shared common purpose. The manager never shows his team will have one. Independent people who dislike tight groups might be exactly the people least likely to rally around a shared goal. If the condition fails, the research tells us nothing about how the team will do.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Look for the untriggered condition: a common purpose.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT156-S4-Q16$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$The manager does not treat any factor as individually necessary. He relies on one research finding.$batch02$), ($batch02$B$batch02$, $batch02$The research is relevant; it is about loose versus tight groups. The problem is that it applies only under a condition the manager never establishes.$batch02$), ($batch02$C$batch02$, $batch02$The manager does not need flexible teams to be better *always*. His mistake is ignoring the research's own limit, not exaggerating its size.$batch02$), ($batch02$D$batch02$, $batch02$The research applies only when a common purpose is shared. If independent workers who avoid tight groups struggle to commit to a common purpose, the finding does not apply to them, and "bound to succeed" collapses.$batch02$), ($batch02$E$batch02$, $batch02$The manager does not mix up his own goals with the team's shared goals. He simply never shows there will be a shared goal.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT156-S4-Q16$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
